package agouti_test
import("fmt";"io";"net/http";"strings";"testing";"github.com/sclevine/agouti";"github.com/sclevine/agouti/api")
type baselineTransport struct{seen []string;bodies []string}
func(b *baselineTransport) RoundTrip(r *http.Request)(*http.Response,error){b.seen=append(b.seen,r.Method+" "+r.URL.Path);v:=[]byte{};if r.Body!=nil{v,_=io.ReadAll(r.Body)};b.bodies=append(b.bodies,string(v));body:=`{"value":null}`;switch r.URL.Path{case "/session":body=`{"sessionId":"legacy","status":0}`;case "/session/legacy/title":body=`{"value":"offline form"}`;case "/session/legacy/execute":body=`{"value":42}`};return &http.Response{StatusCode:200,Header:http.Header{},Body:io.NopCloser(strings.NewReader(body)),Request:r},nil}
func TestBaselineLegacyPage(t *testing.T){tr:=&baselineTransport{};p,e:=agouti.NewPage("http://driver.invalid",agouti.HTTPClient(&http.Client{Transport:tr}));if e!=nil{t.Fatal(e)};if e=p.Navigate("https://forms.invalid/contacts");e!=nil{t.Fatal(e)};var n int;if e=p.RunScript("return 42",nil,&n);e!=nil||n!=42{t.Fatalf("%d %v",n,e)};title,e:=p.Title();if e!=nil||title!="offline form"{t.Fatal(title,e)};fmt.Printf("legacy page script=%d title=%q requests=%d\n",n,title,len(tr.seen));if !strings.Contains(tr.bodies[0],"desiredCapabilities"){t.Fatal(tr.bodies[0])}}
func TestBaselineLegacySessionTimeout(t *testing.T){tr:=&baselineTransport{};s:=api.NewWithClient("http://driver.invalid/session/legacy",&http.Client{Transport:tr});if e:=s.SetImplicitWait(125);e!=nil{t.Fatal(e)};if tr.seen[0]!="POST /session/legacy/timeouts/implicit_wait"{t.Fatal(tr.seen)};fmt.Println("legacy timeout endpoint confirmed")}
